<?php
namespace Esteem_Meta_Lead_Capture\Controllers;
class Meta_webhook extends \App\Controllers\App_Controller {
    public function verify() { $s=(new \Esteem_Meta_Lead_Capture\Libraries\Meta_lead_service())->settings(); $mode=(string)($this->request->getGet('hub.mode') ?: $this->request->getGet('hub_mode')); $token=(string)($this->request->getGet('hub.verify_token') ?: $this->request->getGet('hub_verify_token')); $challenge=(string)($this->request->getGet('hub.challenge') ?: $this->request->getGet('hub_challenge')); if($mode==='subscribe' && $token!=='' && $s['verify_token']!=='' && hash_equals((string)$s['verify_token'],$token)) { return $this->response->setStatusCode(200)->setBody($challenge); } return $this->response->setStatusCode(403)->setBody('Verification failed'); }
    public function receive() { $raw=(string)$this->request->getBody(); $s=(new \Esteem_Meta_Lead_Capture\Libraries\Meta_lead_service())->settings(); $sig=(string)$this->request->getHeaderLine('X-Hub-Signature-256'); $valid=$s['app_secret'] && preg_match('/^sha256=([a-f0-9]{64})$/i',$sig,$m) && hash_equals($m[1],hash_hmac('sha256',$raw,$s['app_secret'])); if(!$valid) { (new \Esteem_Meta_Lead_Capture\Libraries\Meta_lead_service())->log_rejection('invalid_signature',hash('sha256',$raw)); return $this->response->setStatusCode(403)->setJSON(array('error'=>'Invalid webhook signature.')); } $payload=json_decode($raw,true); if(!is_array($payload)) { (new \Esteem_Meta_Lead_Capture\Libraries\Meta_lead_service())->log_rejection('invalid_json',hash('sha256',$raw)); return $this->response->setStatusCode(400)->setJSON(array('error'=>'Invalid JSON.')); } $service=new \Esteem_Meta_Lead_Capture\Libraries\Meta_lead_service(); foreach((array)($payload['entry']??array()) as $entry) foreach((array)($entry['changes']??array()) as $change) { if(($change['field']??'')!=='leadgen')continue; $value=(array)($change['value']??array()); $id=preg_replace('/[^0-9A-Za-z_.:-]/','',(string)($value['leadgen_id']??'')); if($id)$service->process($id,(string)($value['page_id']??$entry['id']??''),(string)($value['form_id']??''),'leadgen',$payload); } return $this->response->setStatusCode(200)->setJSON(array('received'=>true)); }
}
